import React from 'react';

import { IBaseObstacle } from '@apps/Obstacles/@types/obstacles.types';
import { ObstacleBadge } from '@apps/Obstacles/components/ObstacleBadge';
import { searchAndSelectObstacleInModalAsync } from '@apps/Obstacles/components/ObstacleSelectModal';
import PageLoader from '@components/PageLoader';
import PohAlert, { AlertVariant } from '@ui-kit/Alert';
import PohButton, { ButtonSize } from '@ui-kit/Button';
import PohInput, { InputTypes } from '@ui-kit/Input';
import PohCol from '@ui-kit/layout/Col';
import PohRow from '@ui-kit/layout/Row';

import OneArticleBody from './OneArticleBody';
import { getOneArticleAsync, updateArticleAsync } from '../@services/articles.service';
import { IArticle } from '../@types/articles.types';

interface IOneArticleEditProps {
  id: number;
  onDataReady?: (article: IArticle) => void;
}

const OneArticleEdit = ({ id, onDataReady }: IOneArticleEditProps) => {
  const [isLoading, setIsLoading] = React.useState(true);
  const [data, setData] = React.useState<IArticle>();
  const [obstacle, setObstacle] = React.useState<IBaseObstacle | null>(null);
  const [text, setText] = React.useState('');
  const [err, setErr] = React.useState<string | undefined>(undefined);

  React.useEffect(() => {
    const init = async () => {
      try {
        setIsLoading(true);

        const d = await getOneArticleAsync(id);
        setData(d);
        setText(d.text);
        setObstacle(d.obstacle);
        onDataReady?.(d);
      } catch (e) {
        setErr((e as Error).message);
      } finally {
        setIsLoading(false);
      }
    };

    init();
  }, [id]);

  if (isLoading) {
    return <PageLoader />;
  }

  if (err) {
    return <PohAlert variant={AlertVariant.Danger}>{err}</PohAlert>;
  }

  if (!data) {
    return <PohAlert>No data</PohAlert>;
  }

  return (
    <article className="d-flex flex-column" style={{ gap: 12 }}>
      <PohRow>
        <PohCol sm={6}>
          <PohInput
            onRealChange={async (v: string) => {
              await updateArticleAsync({ id, name: v });
              onDataReady?.({ ...data, name: v });
            }}
            defaultValue={data.name}
          />
        </PohCol>
        <PohCol sm={6}>
          {!obstacle && (
            <PohButton
              onClick={async () => {
                const obs = await searchAndSelectObstacleInModalAsync({
                  query: data.name,
                });
                setObstacle(obs);
                await updateArticleAsync({ id, id_obstacle: obs.id });
                onDataReady?.({ ...data, obstacle: obs });
              }}
              size={ButtonSize.Small}
            >
              Привязать к POI
            </PohButton>
          )}
          {obstacle && (
            <span className="d-flex align-items-center horizontal-gapped">
              <small>Привязано к точке: </small>
              <ObstacleBadge obstacle={obstacle} />
              <PohButton
                onClick={async () => {
                  setObstacle(null);
                  await updateArticleAsync({ id, id_obstacle: null });
                  onDataReady?.({ ...data, obstacle: null });
                }}
                className="ms-auto"
                size={ButtonSize.Small}
              >
                Отвязать
              </PohButton>
            </span>
          )}
        </PohCol>
      </PohRow>
      <PohRow>
        <PohCol sm={6}>
          <PohInput
            placeholder="Текст"
            type={InputTypes.textarea}
            onRealChange={async (v: string) => {
              await updateArticleAsync({ id, text: v });
              onDataReady?.({ ...data, text: v });
            }}
            value={text}
            onChange={setText}
            style={{ overflowY: 'auto', height: 600 }}
          />
        </PohCol>
        <PohCol sm={6}>
          <div style={{ overflowY: 'auto', maxHeight: 600 }}>
            <OneArticleBody text={text} />
          </div>
        </PohCol>
      </PohRow>
    </article>
  );
};

export default OneArticleEdit;
